import{_ as e,o as t,c as i,ag as s}from"./chunks/framework.D5hoimZQ.js";const A=JSON.parse('{"title":"科学日报 · 2026-10-25（生物医学 / 细胞死亡 / 线粒体 DNA 外流）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-25-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-25-biomed.md"}'),n={name:"topics/biomedicine/science-daily-2026-10-25-biomed.md"};function c(r,o,a,d,l,g){return t(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-25-生物医学-细胞死亡-线粒体-dna-外流" tabindex="-1">科学日报 · 2026-10-25（生物医学 / 细胞死亡 / 线粒体 DNA 外流） <a class="header-anchor" href="#科学日报-·-2026-10-25-生物医学-细胞死亡-线粒体-dna-外流" aria-label="Permalink to &quot;科学日报 · 2026-10-25（生物医学 / 细胞死亡 / 线粒体 DNA 外流）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> — 第44期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-25-线粒体-dna-如何「漏」出细胞器——bak-bax-组装出一个专门的复合体" tabindex="-1">科学日报 2026-10-25：线粒体 DNA 如何「漏」出细胞器——BAK/BAX 组装出一个专门的复合体 <a class="header-anchor" href="#科学日报-2026-10-25-线粒体-dna-如何「漏」出细胞器——bak-bax-组装出一个专门的复合体" aria-label="Permalink to &quot;科学日报 2026-10-25：线粒体 DNA 如何「漏」出细胞器——BAK/BAX 组装出一个专门的复合体&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ DOI: 10.1126/science.aea2181</p></blockquote><ul><li>背景：凋亡调节蛋白 <strong>BAX 与 BAK</strong> 被激活后形成<strong>同源寡聚体</strong>，触发<strong>线粒体外膜通透化（MOMP）</strong> → 激活<strong>凋亡体（apoptosome）与 caspase</strong>。但存在一条<strong>岔路</strong>：<strong>BAX–BAK 被激活而凋亡体未被激活</strong>时，细胞会进入<strong>持续性 mtDNA 外流 + 不依赖 caspase 的死亡</strong>。这条岔路的<strong>分子基础此前不清楚</strong>。</li><li>本篇的分子答案：纯化出一个<strong>大分子复合体</strong>，成员包括 <strong>BAK、BAX、激活型 BH3-only 蛋白、电压依赖性阴离子通道 VDAC1/VDAC2、prohibitins</strong>；该复合体<strong>能够从线粒体质体（mitoplast）中释放 mtDNA</strong>。</li><li>机制链：<strong>BAX–BAK 激活 → VDAC 关闭 → 线粒体钙内流 → mtDNA 外流</strong>。</li><li>遗传学判据（把「谁负责哪一段」钉死）： <ul><li><strong>敲除 VDAC1、VDAC2 或 prohibitins</strong> → 阻断 <strong>BAX–BAK 激活诱导的 mtDNA 外流与不依赖 caspase 的死亡</strong>；</li><li><strong>却不影响 MOMP</strong>，也<strong>不影响线粒体内膜疝出（herniation）</strong>。</li><li>⇒ 结论：<strong>细胞色素 c 与 mtDNA 的外流由不同的 BAX–BAK 复合体分别调控</strong>（不是同一个「大孔」的两种产物）。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>neuroscience</code>）： <ol><li><strong>「同一个上游开关，下游分成两条独立通道」</strong> —— 过去把 MOMP 当成一个「事件」，本条说明它其实是<strong>一组可分别寻址的复合体</strong>：一个负责 cytochrome c（走 caspase 凋亡），一个负责 mtDNA（走免疫原性/炎症死亡）。<strong>这条区分的临床价值巨大</strong>：mtDNA 外流是 <strong>cGAS-STING 型固有免疫激活</strong>与多种炎症性疾病的共同环节，而阻断它<strong>不伤及经典凋亡</strong> —— 意味着<strong>理论上可以「只关掉炎症性死亡，保留正常凋亡」</strong>。</li><li>与本库 <code>topics/biomedicine/anastasis-cancer-cell-recovery.md</code>（细胞凋亡逆转现象）合看：<strong>「细胞死亡不是二值事件」</strong> 这一主线又多一个证据 —— 既有「凋亡后退回」（anastasis），又有「同样触发 MOMP 却走不同死亡路径」（本条）。可迁移判据：<strong>遇到「某个开关触发某结果」的叙述时，先问『该开关是否还开了第二条通道、而那条通道被忽略』。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第44期 科学板块</p></blockquote><p>关键词：BAX、BAK、同源寡聚体、线粒体外膜通透化 MOMP、凋亡体、caspase、mtDNA 外流、不依赖 caspase 死亡、激活型 BH3-only、VDAC1、VDAC2、prohibitins、线粒体质体释放 mtDNA、VDAC 关闭、线粒体钙内流、敲除 VDAC/prohibitins 阻断而不影响 MOMP、内膜疝出、cytochrome c 与 mtDNA 分属不同复合体、cGAS-STING、只关炎症死亡保留凋亡、细胞死亡非二值</p><p>关联：<code>topics/biomedicine/anastasis-cancer-cell-recovery.md</code>（凋亡逆转）、<code>topics/biomedicine/science-daily-2026-10-23-biomed.md</code>（蛋白稳态/衰老）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>、<code>topics/biomedicine/index.md</code></p>',10)])])}const p=e(n,[["render",c]]);export{A as __pageData,p as default};
